# Synthetic teaching examples; base R and recommended survival package.
set.seed(905)
blue<-'#287f91';orange<-'#bd633e'
start<-function(id,k){png(sprintf('assets/gallery-%s-%d.png',id,k),1100,800,res=130);par(mar=c(5,5,4,2),las=1,bty='l')}
# Time to seed germination, with right censoring.
group<-rep(c('Control','Treatment'),each=30);event<-rexp(60,rate=rep(c(.09,.14),each=30));follow<-runif(60,8,16)
d<-data.frame(seed=1:60,group=group,time=pmin(event,follow),germinated=as.integer(event<=follow));write.csv(d,'data/gallery-survival.csv',row.names=FALSE)
fit<-survival::survfit(survival::Surv(time,germinated)~group,data=d,conf.type='log-log')
for(k in 1:2){start('survival',k);plot(fit,col=c(blue,orange),lty=1:2,lwd=2,conf.int=FALSE,mark.time=TRUE,pch=3,xlim=c(0,16),ylim=c(0,1),xlab='Days since sowing',ylab='Estimated probability of not yet germinating');if(k==2)for(g in 1:2){sg<-survival::survfit(survival::Surv(time,germinated)~1,data=d[d$group==c('Control','Treatment')[g],],conf.type='log-log');lines(c(0,sg$time),c(1,sg$lower),type='s',lty=3,col=c(blue,orange)[g]);lines(c(0,sg$time),c(1,sg$upper),type='s',lty=3,col=c(blue,orange)[g])};legend('topright',c('Control','Treatment'),col=c(blue,orange),lty=1:2,bty='n');mtext(if(k==1)'Crosses: right-censored seeds' else 'Dotted limits: pointwise 95% confidence intervals; crosses: censoring',side=3,line=.8,cex=.8);dev.off()}
# Forest-style effects from four illustrative independent experiments.
f<-data.frame(experiment=paste('Experiment',1:4),difference=c(-.8,-.4,-.2,.1),SE=c(.15,.12,.18,.16));f$low<-f$difference-1.96*f$SE;f$high<-f$difference+1.96*f$SE;write.csv(f,'data/gallery-forest.csv',row.names=FALSE)
for(k in 1:2){start('forest',k);par(mar=c(5,8,3,2));o<-if(k==1)4:1 else order(f$SE,decreasing=TRUE);plot(f$difference[o],1:4,xlim=c(-1.3,.6),ylim=c(.5,4.5),yaxt='n',pch=15,col=blue,xlab='Mean difference in growth (treatment − control, mm/day)',ylab='');segments(f$low[o],1:4,f$high[o],1:4,col=blue,lwd=2);abline(v=0,lty=2,col='grey50');axis(2,1:4,f$experiment[o],tick=FALSE);mtext('Squares: estimates; lines: 95% normal-approximation intervals',side=3,line=.5,cex=.85);dev.off()}
# Paired assay agreement, not independent groups.
a<-seq(10,90,length.out=40)+rnorm(40,0,2);b<-a+4+rnorm(40,0,4);av<-(a+b)/2;delta<-b-a;bias<-mean(delta);lim<-bias+c(-1,1)*1.96*sd(delta)
write.csv(data.frame(sample=1:40,method_A=a,method_B=b),'data/gallery-agreement.csv',row.names=FALSE)
for(k in 1:2){start('blandaltman',k);plot(av,delta,pch=19,col=blue,xlab='Mean of methods A and B (ng/mL)',ylab='Difference: B − A (ng/mL)',ylim=c(-10,20));abline(h=0,col='grey80');if(k==2){abline(h=bias,lwd=2);abline(h=lim,lty=2);legend('topright',c(sprintf('Mean bias: %.1f',bias),sprintf('Limits of agreement: %.1f to %.1f',lim[1],lim[2])),lty=c(1,2),bty='n',cex=.85)};dev.off()}
# Raincloud: half density, compact box, and measurements.
cy<-read.csv('data/gallery-dose.csv');groups<-unique(cy$condition)
for(k in 1:2){start('raincloud',k);par(mar=c(5,8,3,2));n<-if(k==1)1 else 3;plot(NA,xlim=c(0,45),ylim=c(.5,n+.65),yaxt='n',xlab='Cytokine concentration (ng/mL)',ylab='');axis(2,1:n,groups[1:n],tick=FALSE);for(i in 1:n){v<-cy$concentration[cy$condition==groups[i]];den<-density(v,bw=1,from=min(v),to=max(v));col<-c(blue,orange,'#666666')[i];polygon(c(den$x,rev(den$x)),c(i+.08+den$y*2,rep(i+.08,length(den$x))),col=adjustcolor(col,.35),border=col);boxplot(v,at=i,horizontal=TRUE,add=TRUE,axes=FALSE,boxwex=.08,col='white',outline=FALSE);points(v,rep(i-.2,length(v))+runif(length(v),-.05,.05),pch=19,cex=.65,col=col)};dev.off()}
# Toy genome locus; coordinate alignment is retained in every track.
pos<-seq(1,1000);cov1<-round(5+45*exp(-((pos-300)/90)^2)+30*exp(-((pos-740)/120)^2));cov2<-round(5+20*exp(-((pos-300)/90)^2)+55*exp(-((pos-740)/120)^2));write.csv(data.frame(position=pos,control=cov1,treatment=cov2),'data/gallery-genome.csv',row.names=FALSE)
for(k in 1:2){start('genome',k);layout(matrix(seq_len(k+1),k+1),heights=c(rep(2,k),1));for(i in 1:k){par(mar=c(0,5,2,2),las=1,xaxs='i');v<-if(i==1)cov1 else cov2;plot(pos,v,type='h',col=if(i==1)blue else orange,ylim=c(0,65),xlim=c(1,1000),xaxt='n',xlab='',ylab='Read depth',main=if(i==1)'Control' else 'Treatment')};par(mar=c(5,5,1,2),xaxs='i');plot(NA,xlim=c(1,1000),ylim=c(0,1),yaxt='n',xlab='Position in example locus (bp)',ylab='');arrows(c(150,880),c(.5,.5),c(420,600),c(.5,.5),length=.1,lwd=2);for(r in list(c(180,250),c(320,400),c(620,700),c(780,850)))rect(r[1],.35,r[2],.65,col='grey70');text(c(280,740),.85,c('Gene A (+)','Gene B (−)'),cex=.9);dev.off()}
